 "content": "from collections import Counter, deque


def transform(grid):
    """Project non-background tile-interior colors through aligned zero gaps."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    cores = []

    # Repeated framed tiles are separate 4-connected nonzero components.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            # Ignore clipped edge fragments and extract the tile's inner area.
            if r1-r0 >= 2 and c1-c0 >= 2:
                core = [(y, x, grid[y][x])
                        for y in range(r0+1, r1)
                        for x in range(c0+1, c1)]
                if core:
                    cores.extend(core)

    if not cores:
        return out
    background = Counter(color for _, _, color in cores).most_common(1)[0][0]

    # Each non-background core cell sends horizontal and vertical rays; only
    # zero cells are painted, so the existing tile pattern remains untouched.
    sources = [(r, c, color) for r, c, color in cores if color != background]
    for r, c, color in sources:
        for x in range(w):
            if grid[r][x] == 0:
                out[r][x] = color
        for y in range(h):
            if grid[y][c] == 0:
                out[y][c] = color
    return out


if __name__ == '__main__':
    # Quick local smoke test; the benchmark harness imports transform().
    pass
